package com.aadil.ecommerce.controllers;import com.aadil.ecommerce.dtos.InvitationDTO;import com.aadil.ecommerce.responses.APIResponse;import com.aadil.ecommerce.services.AdminService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.security.NoSuchAlgorithmException;import java.time.LocalDateTime;@RestController@RequestMapping ("/api/admin")@Validated@RequiredArgsConstructorpublic class AdminController {    private final AdminService adminService;    @PostMapping("/invitation-link")    public ResponseEntity<APIResponse<String>> adminInvitationLink (@Valid @RequestBody InvitationDTO dto) throws NoSuchAlgorithmException {        String inviteLink = adminService.adminInvitation(dto);        APIResponse<String> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(201);        apiResponse.setMessage("Invitation link is created successfully");        apiResponse.setData(inviteLink);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.CREATED);    }}